"use client"

import React, { useState } from "react"
import { Check, Copy } from "lucide-react"

export interface AiCodeBlockProps {
  language: string
  code: string
  filename?: string
  className?: string
}

export default function AiCodeBlock({
  language,
  code,
  filename,
  className = "",
}: AiCodeBlockProps) {
  const [isCopied, setIsCopied] = useState(false)

  const copyToClipboard = async () => {
    if (!code) return
    try {
      await navigator.clipboard.writeText(code)
      setIsCopied(true)
      setTimeout(() => setIsCopied(false), 2000)
    } catch (err) {
      console.error("Failed to copy code: ", err)
    }
  }

  return (
    <div className={`my-4 overflow-hidden rounded-lg border border-border bg-[#0d1117] ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between bg-[#161b22] px-4 py-2 text-xs text-muted-foreground">
        <div className="flex items-center gap-2">
          {filename ? (
            <span className="font-semibold text-foreground/80">{filename}</span>
          ) : (
            <span className="uppercase">{language}</span>
          )}
        </div>
        <button
          onClick={copyToClipboard}
          className="flex items-center gap-1.5 rounded-md px-2 py-1 transition-colors hover:bg-muted/30 hover:text-foreground"
          aria-label="Copy code"
        >
          {isCopied ? (
            <>
              <Check className="h-3.5 w-3.5 text-emerald-500" />
              <span>Copied</span>
            </>
          ) : (
            <>
              <Copy className="h-3.5 w-3.5" />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>

      {/* Code Body */}
      <div className="overflow-x-auto p-4">
        <pre className="text-sm text-foreground/90 font-mono">
          <code className={`language-${language}`}>{code}</code>
        </pre>
      </div>
    </div>
  )
}
